package com.hmdp.ai.infrastructure.persistence;
import com.hmdp.ai.domain.run.*;import com.hmdp.ai.shared.id.AiIdGenerator;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
import java.time.Instant;import java.util.concurrent.atomic.AtomicInteger;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class JdbcMemoryRepositorySqlContractTest {@Test void completionWritesBindEveryPlaceholder(){AtomicInteger statements=new AtomicInteger();JdbcTemplate jdbc=mock(JdbcTemplate.class,invocation->{
    if("update".equals(invocation.getMethod().getName())&&invocation.getArguments().length>0&&invocation.getArgument(0)instanceof String){String sql=invocation.getArgument(0);Object[]raw=invocation.getArguments();Object[]args=raw.length==2&&raw[1]instanceof Object[]?(Object[])raw[1]:java.util.Arrays.copyOfRange(raw,1,raw.length);assertThat(args).as(sql).hasSize((int)sql.chars().filter(v->v=='?').count());statements.incrementAndGet();return 1;}return org.mockito.Answers.RETURNS_DEFAULTS.answer(invocation);});
    JdbcMemoryRepository repository=new JdbcMemoryRepository(jdbc,new AiIdGenerator());AgentRunRecord run=new AgentRunRecord("run","t","w","u","s","c","a",1,RunStatus.COMPLETED,"BLOCKING","{\"text\":\"hello\"}","{}","{}","{}","{}","{}","trace",null,1,null,null,Instant.now(),Instant.now(),Instant.now(),Instant.now(),Instant.now());
    repository.recordCompletedRun(run,"hello","{}","answer","[]","{}",null,null);repository.saveWorkingSnapshot("t","w","run","c","{}",Instant.now().plusSeconds(60),"u");assertThat(statements.get()).isEqualTo(5);}}
